function requireCondition(value,message){if(!value)throw Error(message);}
async function fixture(role,{listDelay=0,archiveDelay=0,phase='prepared'}={}){let teamReads=0;const expires=Date.now()+60000;const context=await browser.newContext({viewport:{width:1280,height:900}}),page=await context.newPage(),calls=[],errors=[],account=`00000000-0000-4000-8000-00000000000${role==='owner'?1:role==='editor'?2:3}`;await context.tracing.start({screenshots:true,snapshots:true,sources:true});page.on('pageerror',e=>errors.push(e.message));await page.route(`${endpoint}/**`,async route=>{const req=route.request(),u=new URL(req.url()),headers={'Access-Control-Allow-Origin':'*','Content-Type':'application/json'};if(req.method()==='OPTIONS'){await route.fulfill({status:204,headers:{...headers,'Access-Control-Allow-Headers':'*','Access-Control-Allow-Methods':'*'},body:''});return;}if(u.pathname==='/auth/v1/logout'){calls.push({type:'auth-logout'});await route.fulfill({status:204,headers,body:''});return;}if(u.pathname==='/auth/v1/token'){calls.push({type:'auth-fixture',role});await route.fulfill({headers,body:JSON.stringify({access_token:'independent-fixture-token',user:{id:account},expires_in:3600})});return;}if(u.pathname==='/rest/v1/scenario_snapshots'){calls.push({type:'public-list'});if(listDelay)await new Promise(r=>setTimeout(r,listDelay));await route.fulfill({headers,body:JSON.stringify([{id:shared.id,content_hash:shared.contentHash,created_at:shared.createdAt,expires_at:shared.accessExpiresAt}])});return;}if(u.pathname==='/rest/v1/scenario_comments'){calls.push({type:'comments',method:req.method(),body:req.postData()});await route.fulfill({headers,body:'[]'});return;}if(u.pathname==='/functions/v1/scenario-sync'){const wire=req.postDataJSON();calls.push({type:'edge',action:wire.action,input:wire.input});let data;if(wire.action==='projects')data=role==='owner'?[{projectId:remote.project.projectId,name:remote.project.name,serverRevision:'1',role:'owner'}]:role==='editor'?[{projectId:editorImage.projectId,name:null,serverRevision:'1',role:'editor'}]:[];else if(wire.action==='shared_snapshot')data=shared;else if(wire.action==='team_read'){data={...structuredClone(editorImage),authorizationRevision:teamReads++?'2':'1',authorizationExpiresAt:null};if(data.authorizationRevision==='2'){delete data.documents[0].fields.name;data.contentHash=sha(data.documents);}}else if(wire.action==='pull')data=remote;else if(wire.action==='apply'){if(phase==='prepared'){await route.fulfill({status:503,headers,body:JSON.stringify({code:'SYNC_UNAVAILABLE'})});return;}const op=wire.input;data=structuredClone(JSON.parse(readFileSync(`${root}/fixed-fixtures/R9E05-original-c4.json`)).before.conflict);Object.assign(data,{operationId:op.operationId,scope:op.scope,operationHash:sha(op),authorizationExpiresAt:null});}else if(wire.action==='download_archive'){if(archiveDelay)await new Promise(r=>setTimeout(r,archiveDelay));await route.fulfill({status:200,headers:{'Access-Control-Allow-Origin':'*','Content-Type':'application/octet-stream','Content-Length':String(archive.length)},body:archive});return;}else{await route.fulfill({status:500,headers,body:JSON.stringify({code:'UNEXPECTED_FIXTURE_ACTION',action:wire.action})});return;}await route.fulfill({headers,body:JSON.stringify(data)});return;}await route.fulfill({status:404,headers,body:'{}'});});return {context,page,calls,errors,account,expires};}
async function login(f,query=''){await f.page.goto(url+query);await f.page.getByRole('button',{name:'アカウント・専用同期',exact:true}).click();await f.page.getByLabel('専用Supabase URL',{exact:true}).fill(endpoint+'/');await f.page.getByLabel('公開用APIキー',{exact:true}).fill('sb_publishable_independent_fixture_only');await f.page.getByRole('button',{name:'接続設定を保持',exact:true}).click();await f.page.getByLabel('メール',{exact:true}).fill('independent@example.invalid');await f.page.getByLabel('パスワード',{exact:true}).fill('fixture-not-real-password');await f.page.getByRole('button',{name:'認証してアカウント領域を開く',exact:true}).click();await f.page.getByRole('button',{name:'限定版の閲覧・指摘',exact:true}).waitFor();await f.page.getByRole('button',{name:'認証してアカウント領域を開く',exact:true}).waitFor({state:'visible'});}
async function run(id,fn){if(id!=='R9UIE07-prepared')return;const f=await fixture((id.startsWith('R9UE')||id.startsWith('R9UI')||id.startsWith('R9UL'))?'editor':id.startsWith('R9UR')?'owner':'reviewer',{listDelay:id==='R9US01'?400:0,archiveDelay:id==='R9UR02'?1200:0,phase:id.endsWith('conflict')?'conflict':'prepared'});let status='pass',failure='',observation={};try{observation=await fn(f)||{};}catch(e){status='fail';failure=e.stack||String(e);}await f.page.screenshot({path:`${art}/${id}.png`,fullPage:true});writeFileSync(`${art}/${id}-body.txt`,await f.page.locator('body').innerText());await f.context.tracing.stop({path:`${art}/${id}.zip`});const result={id,status,expected:'Correct behavior, not observed-bad success',failure,observation,calls:f.calls,pageErrors:f.errors,environment:'Production Chromium153 at isolated5395, HTTPS backend mocks'};writeFileSync(`${art}/${id}.json`,JSON.stringify(result,null,2)+'\n');results.push(result);console.log(JSON.stringify({id,status,failure:failure.split('\n')[0],observation,calls:f.calls.map(c=>c.action??c.type),pageErrors:f.errors}));await f.context.close();}
async function enterEditor(f){await login(f);await f.page.getByRole('button',{name:'接続先から取得',exact:true}).click();await f.page.getByRole('button',{name:'許可された作品を確認',exact:true}).click();await f.page.getByRole('button',{name:'許可項目を編集',exact:true}).click();await f.page.getByRole('button',{name:'現在の権限で項目を取得',exact:true}).click();await f.page.getByRole('textbox',{name:/^name/}).first().waitFor();}
async function tools(f){return f.page.evaluate(async account=>{const db=await new Promise((resolve,reject)=>{const request=indexedDB.open('scenario-manager-account-'+account);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});try{return await new Promise((resolve,reject)=>{const request=db.transaction('authorToolDrafts','readonly').objectStore('authorToolDrafts').getAll();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}finally{db.close();}},f.account);}
async function editedTools(f,text){await f.page.getByRole('textbox',{name:/^name/}).first().fill(text);for(let i=0;i<50;i++){const rows=await tools(f);if(JSON.stringify(rows).includes(text)){await f.page.waitForTimeout(30);return rows;}await f.page.waitForTimeout(30);}throw Error('REVIEW_FIXTURE_DRAFT_NOT_PERSISTED');}

